package top.hxzmc.community;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.security.cert.X509Certificate;import java.util.*;import javax.net.ssl.*;import org.json.*;
/** Shared, JVM-testable desktop-compatible invitation, framing and certificate pinning. */
public final class GameLobbyWire {
    private static String b64(byte[] bytes){return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);}
    private static int port(int value)throws IOException{if(value<1||value>65535)throw new IOException("端口无效");return value;}
    static String hex(byte[] bytes){StringBuilder out=new StringBuilder();for(byte b:bytes)out.append(String.format(Locale.ROOT,"%02x",b&255));return out.toString();}
    public static JSONObject parseInvitation(String raw)throws Exception {if(raw==null||raw.length()>16000)throw new IOException("请粘贴完整的房间邀请");String text=raw.trim();java.util.regex.Matcher match=java.util.regex.Pattern.compile("hxz-?room://(?:join/|/join/)?([A-Za-z0-9_-]+)",java.util.regex.Pattern.CASE_INSENSITIVE).matcher(text);String code=match.find()?match.group(1):text.replaceFirst("/$","");if(!code.matches("[A-Za-z0-9_-]{40,12000}"))throw new IOException("请粘贴完整的 HXZROOM 邀请");JSONObject v;try{v=new JSONObject(new String(Base64.getUrlDecoder().decode(code),StandardCharsets.UTF_8));}catch(Exception e){throw new IOException("房间邀请无法解析");}JSONArray hosts=v.optJSONArray("hosts");if(!Integer.valueOf(1).equals(v.opt("v"))||!v.optString("id").matches("[-\\w]{16,80}")||!v.optString("key").matches("[-\\w]{43}")||!v.optString("fingerprint").matches("[a-f0-9]{64}")||hosts==null||hosts.length()>8||hosts.length()==0&&!Boolean.TRUE.equals(v.opt("p2p"))||!v.has("name")||!(v.opt("name") instanceof String)||v.getString("name").length()>80)throw new IOException("房间邀请格式无效");if(!(v.opt("port") instanceof Number)||((Number)v.opt("port")).doubleValue()!=v.optInt("port"))throw new IOException("房间端口无效");port(v.optInt("port"));for(int i=0;i<hosts.length();i++){String h=hosts.getString(i);if(!h.matches("[0-9A-Fa-f:.]+")||!literalAddress(h))throw new IOException("邀请地址无效");}if(!(v.opt("expires") instanceof Number)||!Double.isFinite(((Number)v.opt("expires")).doubleValue())||v.optLong("expires")<System.currentTimeMillis())throw new IOException("房间邀请已过期，请向房主获取新邀请");if(v.has("game")&&!v.isNull("game")&&!(v.opt("game") instanceof JSONObject))throw new IOException("房间游戏配置无效");validateGame(v.optJSONObject("game"));return v;}
    private static boolean literalAddress(String h){try{if(h.contains(":"))return InetAddress.getByName(h) instanceof Inet6Address;String[] parts=h.split("\\.",-1);if(parts.length!=4)return false;for(String p:parts)if(!p.matches("0|[1-9][0-9]{0,2}")||Integer.parseInt(p)>255)return false;return true;}catch(Exception e){return false;}}
    static void validateGame(JSONObject g)throws IOException {if(g==null)return;if(!(g.opt("minecraft") instanceof String)||!(g.opt("loader") instanceof String)||!(g.opt("loaderVersion") instanceof String)||!(g.opt("mods") instanceof String)||!(g.opt("modCount") instanceof Number)||((Number)g.opt("modCount")).doubleValue()!=g.optInt("modCount")||!g.optString("minecraft").matches("[-\\w.+]{1,100}")||!Arrays.asList("","fabric","quilt","forge","neoforge").contains(g.optString("loader"))||!g.optString("loaderVersion").matches("[-\\w.+]{0,100}")||g.optInt("modCount",-1)<0||g.optInt("modCount")>10000||!g.optString("mods").matches("[a-f0-9]{64}|"))throw new IOException("房间游戏配置无效");if(g.has("platform")&&!Arrays.asList("android","desktop").contains(g.optString("platform"))||g.has("compatibilityPolicy")&&(!g.optString("platform").equals("android")||!g.optString("compatibilityPolicy").equals("hxz-android-1")))throw new IOException("房间平台兼容配置无效");}
    public static String invitation(JSONObject value){try{JSONObject v=new JSONObject();for(String key:new String[]{"v","id","key","fingerprint","name","hosts","p2p","port","expires","game"})v.put(key,value.opt(key));return "hxz-room://join/"+b64(v.toString().getBytes(StandardCharsets.UTF_8));}catch(Exception e){return "";}}
    static JSONObject readLine(Socket socket)throws Exception {ByteArrayOutputStream out=new ByteArrayOutputStream();InputStream input=socket.getInputStream();int b;while((b=input.read())!=-1){if(b==10)return new JSONObject(out.toString("UTF-8"));if(out.size()>=8192)throw new IOException("房间响应过大");out.write(b);}throw new IOException("房主已断开连接");}
    static void writeLine(Socket socket,JSONObject value)throws Exception {socket.getOutputStream().write((value.toString()+"\n").getBytes(StandardCharsets.UTF_8));socket.getOutputStream().flush();}

    public static SSLSocket secure(Socket raw,JSONObject target)throws Exception {
        TrustManager[] trust={new X509TrustManager(){public X509Certificate[]getAcceptedIssuers(){return new X509Certificate[0];}public void checkClientTrusted(X509Certificate[]c,String a){}public void checkServerTrusted(X509Certificate[]c,String a)throws java.security.cert.CertificateException {try{if(c.length<1||!hex(MessageDigest.getInstance("SHA-256").digest(c[0].getEncoded())).equals(target.optString("fingerprint")))throw new java.security.cert.CertificateException("房主证书与邀请不一致");}catch(java.security.cert.CertificateException e){throw e;}catch(Exception e){throw new java.security.cert.CertificateException(e);}}}};
        SSLContext ssl=SSLContext.getInstance("TLS");ssl.init(null,trust,new SecureRandom());SSLSocket secure=(SSLSocket)ssl.getSocketFactory().createSocket(raw,"hxz-room",target.getInt("port"),true);secure.setEnabledProtocols(Arrays.stream(secure.getSupportedProtocols()).filter(v->v.equals("TLSv1.2")||v.equals("TLSv1.3")).toArray(String[]::new));secure.setSoTimeout(10000);secure.startHandshake();return secure;
    }
}
